INSERT INTO regimens VALUES('BHH-CATALOG-037','Cetuximab + Docetaxel + Cisplatin + Fluorouracil regimen','มะเร็งคอหูจมูก (Locally Advanced HNSCC)','มะเร็งคอหูจมูก (Locally Advanced HNSCC)','["Cetuximab + Docetaxel + Cisplatin + Fluorouracil regimen","มะเร็งคอหูจมูก (Locally Advanced HNSCC)","มะเร็งคอหูจมูก (Locally Advanced HNSCC)","Cetuximab","Docetaxel","Cisplatin","Fluorouracil"]','{"ชื่อสูตรยา":"Cetuximab + Docetaxel + Cisplatin + Fluorouracil regimen","ชนิดของมะเร็ง":"มะเร็งคอหูจมูก (Locally Advanced HNSCC)","รอบการรักษา":"3 cycles","รายการยา":[{"ชื่อยา":"Cetuximab","ขนาดยา":"400 mg/m² IV loading, then 250 mg/m² weekly","ความถี่ในการให้":"ทุก 7 วัน","maximum_dose":null},{"ชื่อยา":"Docetaxel","ขนาดยา":"75 mg/m² IV day 1","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Cisplatin","ขนาดยา":"100 mg/m² IV day 1","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Fluorouracil","ขนาดยา":"700 mg/m²/day IV continuous days 1-4","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
