INSERT INTO regimens VALUES('BHH-CATALOG-048','R-CODOX-M/IVAC regimen','มะเร็งต่อมน้ำเหลือง Burkitt (High-Risk)','มะเร็งต่อมน้ำเหลือง Burkitt (High-Risk)','["R-CODOX-M/IVAC regimen","มะเร็งต่อมน้ำเหลือง Burkitt (High-Risk)","มะเร็งต่อมน้ำเหลือง Burkitt (High-Risk)","Rituximab","Cyclophosphamide","Vincristine","Doxorubicin","Methotrexate","Ifosfamide","Etoposide","Cytarabine"]','{"ชื่อสูตรยา":"R-CODOX-M/IVAC regimen","ชนิดของมะเร็ง":"มะเร็งต่อมน้ำเหลือง Burkitt (High-Risk)","รอบการรักษา":"Alternating cycles","รายการยา":[{"ชื่อยา":"Rituximab","ขนาดยา":"375 mg/m² IV day 1","ความถี่ในการให้":"per cycle","maximum_dose":null},{"ชื่อยา":"Cyclophosphamide","ขนาดยา":"800 mg/m² IV days 1-2","ความถี่ในการให้":"R-CODOX-M","maximum_dose":null},{"ชื่อยา":"Vincristine","ขนาดยา":"1.5 mg/m² IV days 1,8","ความถี่ในการให้":"R-CODOX-M","maximum_dose":"2 mg"},{"ชื่อยา":"Doxorubicin","ขนาดยา":"50 mg/m² IV day 1","ความถี่ในการให้":"R-CODOX-M","maximum_dose":null},{"ชื่อยา":"Methotrexate","ขนาดยา":"3 g/m² IV day 10","ความถี่ในการให้":"R-CODOX-M","maximum_dose":null},{"ชื่อยา":"Ifosfamide","ขนาดยา":"1500 mg/m² IV days 1-5","ความถี่ในการให้":"IVAC","maximum_dose":null},{"ชื่อยา":"Etoposide","ขนาดยา":"60 mg/m² IV days 1-5","ความถี่ในการให้":"IVAC","maximum_dose":null},{"ชื่อยา":"Cytarabine","ขนาดยา":"2 g/m² IV BID days 1-5","ความถี่ในการให้":"IVAC","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
