INSERT INTO regimens VALUES('BHH-CATALOG-049','R-HCVAD regimen','มะเร็งต่อมน้ำเหลือง (Lymphoblastic Lymphoma)','มะเร็งต่อมน้ำเหลือง (Lymphoblastic Lymphoma)','["R-HCVAD regimen","มะเร็งต่อมน้ำเหลือง (Lymphoblastic Lymphoma)","มะเร็งต่อมน้ำเหลือง (Lymphoblastic Lymphoma)","Rituximab","Cyclophosphamide","Vincristine","Doxorubicin","Dexamethasone","Methotrexate","Cytarabine"]','{"ชื่อสูตรยา":"R-HCVAD regimen","ชนิดของมะเร็ง":"มะเร็งต่อมน้ำเหลือง (Lymphoblastic Lymphoma)","รอบการรักษา":"Alternating cycles","รายการยา":[{"ชื่อยา":"Rituximab","ขนาดยา":"375 mg/m² IV day 1","ความถี่ในการให้":"per cycle","maximum_dose":null},{"ชื่อยา":"Cyclophosphamide","ขนาดยา":"300 mg/m² IV every 12h days 1-3","ความถี่ในการให้":"odd cycles","maximum_dose":null},{"ชื่อยา":"Vincristine","ขนาดยา":"2 mg IV days 4-5","ความถี่ในการให้":"odd cycles","maximum_dose":"2 mg"},{"ชื่อยา":"Doxorubicin","ขนาดยา":"50 mg/m² IV day 4","ความถี่ในการให้":"odd cycles","maximum_dose":null},{"ชื่อยา":"Dexamethasone","ขนาดยา":"40 mg PO/IV days 1-4 and 11-14","ความถี่ในการให้":"odd cycles","maximum_dose":null},{"ชื่อยา":"Methotrexate","ขนาดยา":"1000 mg/m² IV day 1","ความถี่ในการให้":"even cycles","maximum_dose":null},{"ชื่อยา":"Cytarabine","ขนาดยา":"70 mg/m² IT day 2,7","ความถี่ในการให้":"even cycles","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
