INSERT INTO regimens VALUES('BHH-CATALOG-057','TCH regimen','มะเร็งเต้านม HER2-positive (HER2-positive Breast Cancer)','มะเร็งเต้านม HER2-positive (HER2-positive Breast Cancer)','["TCH regimen","มะเร็งเต้านม HER2-positive (HER2-positive Breast Cancer)","มะเร็งเต้านม HER2-positive (HER2-positive Breast Cancer)","Docetaxel","Carboplatin","Trastuzumab (loading dose)","Trastuzumab (maintenance)"]','{"ชื่อสูตรยา":"TCH regimen","ชนิดของมะเร็ง":"มะเร็งเต้านม HER2-positive (HER2-positive Breast Cancer)","รอบการรักษา":"6 cycles combined chemotherapy, followed by trastuzumab alone to complete 1 year","รายการยา":[{"ชื่อยา":"Docetaxel","ขนาดยา":"75 mg/m² IV day 1","ความถี่ในการให้":"ทุก 21 วัน (6 cycles)","maximum_dose":null},{"ชื่อยา":"Carboplatin","ขนาดยา":"AUC 6 mg/ml/min IV day 1","ความถี่ในการให้":"ทุก 21 วัน (6 cycles)","maximum_dose":"900 mg"},{"ชื่อยา":"Trastuzumab (loading dose)","ขนาดยา":"8 mg/kg IV day 1","ความถี่ในการให้":"cycle 1 เท่านั้น","maximum_dose":null},{"ชื่อยา":"Trastuzumab (maintenance)","ขนาดยา":"6 mg/kg IV","ความถี่ในการให้":"ทุก 21 วัน (total 1 year, about 18 cycles)","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
