INSERT INTO regimens VALUES('BHH-CATALOG-058','FOLFIRI regimen','มะเร็งลำไส้ใหญ่ (Colorectal Cancer)','มะเร็งลำไส้ใหญ่ (Colorectal Cancer)','["FOLFIRI regimen","มะเร็งลำไส้ใหญ่ (Colorectal Cancer)","มะเร็งลำไส้ใหญ่ (Colorectal Cancer)","Irinotecan","Leucovorin","Fluorouracil (5-FU) bolus","Fluorouracil (5-FU) continuous infusion"]','{"ชื่อสูตรยา":"FOLFIRI regimen","ชนิดของมะเร็ง":"มะเร็งลำไส้ใหญ่ (Colorectal Cancer)","รอบการรักษา":"12 รอบการรักษา","รายการยา":[{"ชื่อยา":"Irinotecan","ขนาดยา":"180 mg/m² IV day 1","ความถี่ในการให้":"ทุก 14 วัน","maximum_dose":null},{"ชื่อยา":"Leucovorin","ขนาดยา":"400 mg/m² IV day 1","ความถี่ในการให้":"ทุก 14 วัน","maximum_dose":null},{"ชื่อยา":"Fluorouracil (5-FU) bolus","ขนาดยา":"400 mg/m² IV bolus day 1","ความถี่ในการให้":"ทุก 14 วัน","maximum_dose":null},{"ชื่อยา":"Fluorouracil (5-FU) continuous infusion","ขนาดยา":"2400 mg/m² IV over 46h","ความถี่ในการให้":"ทุก 14 วัน","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
