INSERT INTO regimens VALUES('BHH-CATALOG-061','ABVD regimen','มะเร็งต่อมน้ำเหลือง Hodgkin (Hodgkin Lymphoma)','มะเร็งต่อมน้ำเหลือง Hodgkin (Hodgkin Lymphoma)','["ABVD regimen","มะเร็งต่อมน้ำเหลือง Hodgkin (Hodgkin Lymphoma)","มะเร็งต่อมน้ำเหลือง Hodgkin (Hodgkin Lymphoma)","Doxorubicin","Bleomycin","Vinblastine","Dacarbazine"]','{"ชื่อสูตรยา":"ABVD regimen","ชนิดของมะเร็ง":"มะเร็งต่อมน้ำเหลือง Hodgkin (Hodgkin Lymphoma)","รอบการรักษา":"6 รอบการรักษา","รายการยา":[{"ชื่อยา":"Doxorubicin","ขนาดยา":"25 mg/m² IV day 1 and 15","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Bleomycin","ขนาดยา":"10 units/m² IV day 1 and 15","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Vinblastine","ขนาดยา":"6 mg/m² IV day 1 and 15","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Dacarbazine","ขนาดยา":"375 mg/m² IV day 1 and 15","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
