INSERT INTO regimens VALUES('BHH-CATALOG-072','BEP regimen','มะเร็งอัณฑะ (Testicular Cancer)','มะเร็งอัณฑะ (Testicular Cancer)','["BEP regimen","มะเร็งอัณฑะ (Testicular Cancer)","มะเร็งอัณฑะ (Testicular Cancer)","Bleomycin","Etoposide","Cisplatin"]','{"ชื่อสูตรยา":"BEP regimen","ชนิดของมะเร็ง":"มะเร็งอัณฑะ (Testicular Cancer)","รอบการรักษา":"3-4 รอบการรักษา","รายการยา":[{"ชื่อยา":"Bleomycin","ขนาดยา":"30 units IV days 1,8,15","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Etoposide","ขนาดยา":"100 mg/m² IV days 1-5","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Cisplatin","ขนาดยา":"20 mg/m² IV days 1-5","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
