INSERT INTO regimens VALUES('BHH-CATALOG-077','MOPP regimen','มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)','มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)','["MOPP regimen","มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)","มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)","Mechlorethamine","Vincristine","Procarbazine","Prednisone"]','{"ชื่อสูตรยา":"MOPP regimen","ชนิดของมะเร็ง":"มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)","รอบการรักษา":"6 รอบการรักษา","รายการยา":[{"ชื่อยา":"Mechlorethamine","ขนาดยา":"6 mg/m² IV day 1 and 8","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Vincristine","ขนาดยา":"1.4 mg/m² IV day 1 and 8","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":"2 mg"},{"ชื่อยา":"Procarbazine","ขนาดยา":"100 mg/m² PO days 1-10","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Prednisone","ขนาดยา":"40 mg/m² PO days 1-14","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
