INSERT INTO regimens VALUES('BHH-CATALOG-078','BEACOPP regimen','มะเร็งต่อมน้ำเหลือง (Advanced Hodgkin Lymphoma)','มะเร็งต่อมน้ำเหลือง (Advanced Hodgkin Lymphoma)','["BEACOPP regimen","มะเร็งต่อมน้ำเหลือง (Advanced Hodgkin Lymphoma)","มะเร็งต่อมน้ำเหลือง (Advanced Hodgkin Lymphoma)","Bleomycin","Etoposide","Adriamycin (Doxorubicin)","Cyclophosphamide","Oncovin (Vincristine)","Procarbazine","Prednisone"]','{"ชื่อสูตรยา":"BEACOPP regimen","ชนิดของมะเร็ง":"มะเร็งต่อมน้ำเหลือง (Advanced Hodgkin Lymphoma)","รอบการรักษา":"6-8 รอบการรักษา","รายการยา":[{"ชื่อยา":"Bleomycin","ขนาดยา":"10 mg/m² IV day 8","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Etoposide","ขนาดยา":"190 mg/m² IV days 1-3","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Adriamycin (Doxorubicin)","ขนาดยา":"35 mg/m² IV day 1","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Cyclophosphamide","ขนาดยา":"650 mg/m² IV day 1","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Oncovin (Vincristine)","ขนาดยา":"1.4 mg/m² IV day 8","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":"2 mg"},{"ชื่อยา":"Procarbazine","ขนาดยา":"100 mg/m² PO days 1-7","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null},{"ชื่อยา":"Prednisone","ขนาดยา":"40 mg/m² PO days 1-14","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
