INSERT INTO regimens VALUES('BHH-CATALOG-079','DHAP regimen','มะเร็งต่อมน้ำเหลือง (Lymphoma Relapse)','มะเร็งต่อมน้ำเหลือง (Lymphoma Relapse)','["DHAP regimen","มะเร็งต่อมน้ำเหลือง (Lymphoma Relapse)","มะเร็งต่อมน้ำเหลือง (Lymphoma Relapse)","Dexamethasone","Cisplatin","Cytarabine"]','{"ชื่อสูตรยา":"DHAP regimen","ชนิดของมะเร็ง":"มะเร็งต่อมน้ำเหลือง (Lymphoma Relapse)","รอบการรักษา":"4 รอบการรักษา","รายการยา":[{"ชื่อยา":"Dexamethasone","ขนาดยา":"40 mg PO/IV days 1-4","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Cisplatin","ขนาดยา":"100 mg/m² IV day 1","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Cytarabine","ขนาดยา":"2 g/m² IV every 12h day 1","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
