INSERT INTO regimens VALUES('BHH-CATALOG-082','Stanford V regimen','มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)','มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)','["Stanford V regimen","มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)","มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)","Doxorubicin","Vinblastine","Mechlorethamine","Etoposide","Prednisone","Bleomycin"]','{"ชื่อสูตรยา":"Stanford V regimen","ชนิดของมะเร็ง":"มะเร็งต่อมน้ำเหลือง (Hodgkin Lymphoma)","รอบการรักษา":"12 สัปดาห์","รายการยา":[{"ชื่อยา":"Doxorubicin","ขนาดยา":"25 mg/m² IV weeks 1,3,5,7,9,11","ความถี่ในการให้":"ตาม schedule","maximum_dose":null},{"ชื่อยา":"Vinblastine","ขนาดยา":"6 mg/m² IV weeks 1,3,5,7,9,11","ความถี่ในการให้":"ตาม schedule","maximum_dose":null},{"ชื่อยา":"Mechlorethamine","ขนาดยา":"6 mg/m² IV weeks 1,5,9","ความถี่ในการให้":"ตาม schedule","maximum_dose":null},{"ชื่อยา":"Etoposide","ขนาดยา":"60 mg/m² IV weeks 3,7,11","ความถี่ในการให้":"ตาม schedule","maximum_dose":null},{"ชื่อยา":"Prednisone","ขนาดยา":"40 mg PO even weeks","ความถี่ในการให้":"ตาม schedule","maximum_dose":null},{"ชื่อยา":"Bleomycin","ขนาดยา":"5 units/m² IV weeks 2,6,10","ความถี่ในการให้":"ตาม schedule","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
