INSERT INTO regimens VALUES('BHH-CATALOG-131','Rituximab + Bendamustine + Trastuzumab regimen','มะเร็งเต้านม (HER2+ with CD20 Expression)','มะเร็งเต้านม (HER2+ with CD20 Expression)','["Rituximab + Bendamustine + Trastuzumab regimen","มะเร็งเต้านม (HER2+ with CD20 Expression)","มะเร็งเต้านม (HER2+ with CD20 Expression)","Rituximab","Bendamustine","Trastuzumab"]','{"ชื่อสูตรยา":"Rituximab + Bendamustine + Trastuzumab regimen","ชนิดของมะเร็ง":"มะเร็งเต้านม (HER2+ with CD20 Expression)","รอบการรักษา":"6 cycles","รายการยา":[{"ชื่อยา":"Rituximab","ขนาดยา":"375 mg/m² IV day 1","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Bendamustine","ขนาดยา":"90 mg/m² IV days 1-2","ความถี่ในการให้":"ทุก 28 วัน","maximum_dose":null},{"ชื่อยา":"Trastuzumab","ขนาดยา":"8 mg/kg IV loading, then 6 mg/kg","ความถี่ในการให้":"ทุก 21 วัน","maximum_dose":null}]}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
