INSERT INTO regimen_versions(id,regimen_id,version,status,document,revision,previous_version,approved_by,approved_at,approval_comment,published_at,published_by,created_at,created_by,updated_at,updated_by) VALUES('BHH-BREAST-TCH-EVIQ53:1','BHH-BREAST-TCH-EVIQ53','1','published','{"id":"BHH-BREAST-TCH-EVIQ53","version":"1","name":"TCH","cancerGroup":"Breast","indication":"HER2-positive breast cancer — adjuvant TCH reference model","setting":"Adjuvant","intent":"Curative","population":"adult","cycleIntervalDays":21,"cycleCount":17,"status":"published","localApproval":true,"effectiveDate":"2026-10-07","lastReviewed":"2026-10-07","references":[{"label":"eviQ ID 53 — Breast adjuvant TCH","url":"https://www.eviq.org.au/medical-oncology/breast/neoadjuvant-adjuvant/53-breast-adjuvant-tch-docetaxel-carboplatin-tras","accessedDate":"2026-10-07"}],"clinicalNotes":["Local approval recorded per project owner confirmation on 7 October 2026 for this six-regimen pilot registry.","Published pilot registry entry based on the current referenced schedule; local approval is recorded for v2.1.0.","If estimated kidney function is >125 mL/min and AUC6 dose would exceed 900 mg, the reference recommends considering direct measurement of kidney function rather than applying a universal hard 900 mg cap."],"phases":[{"id":"tch-c1","name":"Cycle 1 — loading + combination","cycleStart":1,"cycleEnd":1,"orders":[{"id":"tch-c1-docetaxel","drugId":"docetaxel","drugName":"Docetaxel","dose":{"basis":"bsa","value":75,"unit":"mg","displayDenominator":"m²"},"route":"IV","schedule":{"days":[1],"infusionMinutes":60},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]},{"id":"tch-c1-carboplatin","drugId":"carboplatin","drugName":"Carboplatin","dose":{"basis":"auc","value":6,"unit":"mg","displayDenominator":"AUC"},"route":"IV","schedule":{"days":[1],"infusionMinutes":60},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","clinicalRules":[{"type":"warning_threshold","metric":"kidney_function","operator":"gt","value":125,"message":"Kidney function >125 mL/min: verify the regimen-specific Carboplatin kidney-function method; current TCH reference recommends considering direct measurement rather than an automatic 125 mL/min cap."}],"allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]},{"id":"tch-c1-trastuzumab","drugId":"trastuzumab","drugName":"Trastuzumab","dose":{"basis":"weight","value":8,"unit":"mg","displayDenominator":"kg"},"route":"IV","schedule":{"days":[1],"infusionMinutes":90,"note":"loading dose"},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]}]},{"id":"tch-c2-6","name":"Cycles 2–6 — combination","cycleStart":2,"cycleEnd":6,"orders":[{"id":"tch-c2-docetaxel","drugId":"docetaxel","drugName":"Docetaxel","dose":{"basis":"bsa","value":75,"unit":"mg","displayDenominator":"m²"},"route":"IV","schedule":{"days":[1],"infusionMinutes":60},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]},{"id":"tch-c2-carboplatin","drugId":"carboplatin","drugName":"Carboplatin","dose":{"basis":"auc","value":6,"unit":"mg","displayDenominator":"AUC"},"route":"IV","schedule":{"days":[1],"infusionMinutes":60},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","clinicalRules":[{"type":"warning_threshold","metric":"kidney_function","operator":"gt","value":125,"message":"Kidney function >125 mL/min: verify Carboplatin dosing method and consider measured GFR per protocol/reference."}],"allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]},{"id":"tch-c2-trastuzumab","drugId":"trastuzumab","drugName":"Trastuzumab","dose":{"basis":"weight","value":6,"unit":"mg","displayDenominator":"kg"},"route":"IV","schedule":{"days":[1],"infusionMinutes":30,"note":"subsequent dose"},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]}]},{"id":"tch-c7-17","name":"Cycles 7–17 — trastuzumab maintenance","cycleStart":7,"cycleEnd":17,"orders":[{"id":"tch-maint-trastuzumab","drugId":"trastuzumab","drugName":"Trastuzumab","dose":{"basis":"weight","value":6,"unit":"mg","displayDenominator":"kg"},"route":"IV","schedule":{"days":[1],"infusionMinutes":30,"note":"maintenance"},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]}]}],"alias":["TCH"]}',1,NULL,'v2-approved-import','2026-10-07','Prior local approval recorded in docs/CLINICAL_VALIDATION_REQUIRED.md and confirmed by project owner; imported V2.1.0 exact clinical definition. Original named reviewer unavailable; not a new V3 review.','2026-10-07','v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
