INSERT INTO audit_logs VALUES('BHH-BREAST-TCH-EVIQ53:1:import','regimen_version','BHH-BREAST-TCH-EVIQ53:1','1','import',NULL,'{"id":"BHH-BREAST-TCH-EVIQ53","version":"1","name":"TCH","cancerGroup":"Breast","indication":"HER2-positive breast cancer — adjuvant TCH reference model","setting":"Adjuvant","intent":"Curative","population":"adult","cycleIntervalDays":21,"cycleCount":17,"status":"published","localApproval":true,"effectiveDate":"2026-10-07","lastReviewed":"2026-10-07","references":[{"label":"eviQ ID 53 — Breast adjuvant TCH","url":"https://www.eviq.org.au/medical-oncology/breast/neoadjuvant-adjuvant/53-breast-adjuvant-tch-docetaxel-carboplatin-tras","accessedDate":"2026-10-07"}],"clinicalNotes":["Local approval recorded per project owner confirmation on 7 October 2026 for this six-regimen pilot registry.","Published pilot registry entry based on the current referenced schedule; local approval is recorded for v2.1.0.","If estimated kidney function is >125 mL/min and AUC6 dose would exceed 900 mg, the reference recommends considering direct measurement of kidney function rather than applying a universal hard 900 mg cap."],"phases":[{"id":"tch-c1","name":"Cycle 1 — loading + combination","cycleStart":1,"cycleEnd":1,"orders":[{"id":"tch-c1-docetaxel","drugId":"docetaxel","drugName":"Docetaxel","dose":{"basis":"bsa","value":75,"unit":"mg","displayDenominator":"m²"},"route":"IV","schedule":{"days":[1],"infusionMinutes":60},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]},{"id":"tch-c1-carboplatin","drugId":"carboplatin","drugName":"Carboplatin","dose":{"basis":"auc","value":6,"unit":"mg","displayDenominator":"AUC"},"route":"IV","schedule":{"days":[1],"infusionMinutes":60},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","clinicalRules":[{"type":"warning_threshold","metric":"kidney_function","operator":"gt","value":125,"message":"Kidney function >125 mL/min: verify the regimen-specific Carboplatin kidney