["NO_ROUND","BHH_NEAREST_1MG_DEFAULT"]},{"id":"bep-etoposide","drugId":"etoposide","drugName":"Etoposide","dose":{"basis":"bsa","value":100,"unit":"mg","displayDenominator":"m²"},"route":"IV","schedule":{"days":[1,2,3,4,5]},"roundingProfileId":"BHH_NEAREST_10MG_DEFAULT","allowedRoundingPolicies":["NO_ROUND","BHH_NEAREST_10MG_DEFAULT"]}]}],"alias":["BEP — metastatic testicular germ cell"]}',1,NULL,'v2-approved-import','2026-10-07','Prior local approval recorded in docs/CLINICAL_VALIDATION_REQUIRED.md and confirmed by project owner; imported V2.1.0 exact clinical definition. Original named reviewer unavailable; not a new V3 review.','2026-10-07','v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'v2-approved-import');
